import 'fake-indexeddb/auto';

import { beforeEach, describe, expect, it, vi } from 'vitest';

vi.mock('../../src/storage/remote', () => ({
  lookupDatabase: vi.fn(),
}));

import { getLastOpenedId, listRemembered, remember, setLastOpenedId } from '../../src/storage/registry';
import { lookupDatabase } from '../../src/storage/remote';
import { restoreLastOpened } from '../../src/storage/resume';

const lookup = vi.mocked(lookupDatabase);

/** Drop the registry database so each test starts empty. */
function reset(): Promise<void> {
  return new Promise((resolve) => {
    const request = indexedDB.deleteDatabase('upm-registry');
    request.onsuccess = () => resolve();
    request.onerror = () => resolve();
    request.onblocked = () => resolve();
  });
}

function remote(id: string, path: string) {
  return {
    id,
    path,
    name: path.split('/').pop() ?? path,
    size: 64,
    mtime: 0,
    canWrite: true,
  };
}

beforeEach(async () => {
  await reset();
  lookup.mockReset();
});

describe('restoreLastOpened', () => {
  it('returns null when no database was opened yet', async () => {
    expect(await restoreLastOpened()).toBeNull();
    expect(lookup).not.toHaveBeenCalled();
  });

  it('returns the last opened database with its remembered label', async () => {
    await remember({ id: 'db-1', label: 'Work', path: 'upm/work.db' });
    await remember({ id: 'db-2', label: 'Home', path: 'upm/home.db' });
    await setLastOpenedId('db-1');
    lookup.mockResolvedValue(remote('db-1', 'upm/work.db'));

    expect(await restoreLastOpened()).toEqual({
      id: 'db-1',
      label: 'Work',
      path: 'upm/work.db',
      canWrite: true,
    });
    expect(await getLastOpenedId()).toBe('db-1');
  });

  it('relinks the database when the server handed out a new file id', async () => {
    await remember({ id: 'old', label: 'Work', path: 'upm/work.db' });
    await setLastOpenedId('old');
    lookup.mockResolvedValue(remote('new', 'upm/work.db'));

    expect(await restoreLastOpened()).toEqual({
      id: 'new',
      label: 'Work',
      path: 'upm/work.db',
      canWrite: true,
    });
    expect(await getLastOpenedId()).toBe('new');
    expect((await listRemembered()).map((item) => item.id)).toEqual(['new']);
  });

  it('returns null but keeps the label when the file has gone', async () => {
    await remember({ id: 'db-1', label: 'Work', path: 'upm/work.db' });
    await setLastOpenedId('db-1');
    lookup.mockResolvedValue(null);

    expect(await restoreLastOpened()).toBeNull();
    expect((await listRemembered())[0]?.label).toBe('Work');
  });

  it('clears a last-opened id whose entry was removed', async () => {
    await remember({ id: 'db-1', label: 'Work', path: 'upm/work.db' });
    await setLastOpenedId('db-2');

    expect(await restoreLastOpened()).toBeNull();
    expect(await getLastOpenedId()).toBeNull();
    expect(lookup).not.toHaveBeenCalled();
  });
});
